  sortStep(1600, 'value'),
  filterStep(1500, 'qualified'),
  filterStep(1700, 'all'),
  sortStep(1500, 'touch'),
  filterStep(1600, 'proposal'),
  filterStep(1700, 'all'),
];

export const SESSION: SessionConfig<LeadsView, LeadsAction> = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
