import { REPLY_DRAFT } from './data';

function shownDraftOf(
  draft: string | null,
  shouldReduceMotion: boolean | null
) {
  if (draft !== null) {
    return draft;
  }
  if (shouldReduceMotion) {
    return REPLY_DRAFT.draft;
  }
  return '';
}

function InsertLabel({ isInserted }: { isInserted: boolean }) {
  if (isInserted) {
    return (
      <span className='inline-flex items-center gap-1.5'>
        <CheckIcon />
        {REPLY_DRAFT.inserted}
      </span>
    );
  }
  return <span>{REPLY_DRAFT.insert}</span>;
}

export function ReplyDraft() {
  const [draft, setDraft] = useState<string | null>(null);
  const [isPressed, setIsPressed] = useState(false);
  const [isInserted, setIsInserted] = useState(false);
  const shouldReduceMotion = usePrefersReducedMotion();
  const draftId = useId();
  const steps = [
    ...typingSteps(REPLY_DRAFT.draft, setDraft, {
      startAfter: 1000,
      characterMs: 24,
    }),
    { after: 700, run: () => setIsPressed(true) },
    {
      after: 140,
      run: () => {
        setIsPressed(false);
        setIsInserted(true);
      },
    },
  ];
  const { ref } = useAutoplay(steps, {
    loopAfter: 2400,
    onReset: () => {
      setDraft(null);
      setIsInserted(false);
    },
  });

  function changeDraft(event: React.ChangeEvent<HTMLTextAreaElement>) {
    setDraft(event.target.value);
  }

  function insert() {
    setIsInserted(true);
  }

  return (
    <div ref={ref} className='flex flex-col gap-3'>
      <div className='flex items-start gap-2'>
        <Avatar
          seed={REPLY_DRAFT.incomingFrom}
          role='img'
          aria-label={REPLY_DRAFT.incomingFrom}
          className='size-6'
        />
        <p className='bg-card hairline-ring ring-border rounded-xl rounded-ss-sm px-3 py-2 text-[13px] text-pretty'>
          {REPLY_DRAFT.incoming}
        </p>
      </div>
      <label htmlFor={draftId} className='sr-only'>
        Draft reply
      </label>
      <Textarea
        id={draftId}
        value={shownDraftOf(draft, shouldReduceMotion)}
        onChange={changeDraft}
        placeholder='The draft appears here'
        className='min-h-[6.5rem]'
      />
      <Button size='sm' onClick={insert} className={pressedSolidOf(isPressed)}>
        <Swap swapKey={String(isInserted)}>
          <InsertLabel isInserted={isInserted} />
        </Swap>
      </Button>
    </div>
  );
}

'use client';

import { useInView } from 'motion/react';
import { useRef } from 'react';

import { Settle } from '@/registry/ndeko/ui/settle';

const ENTERED_ONCE = { once: true, margin: '0px 0px -12% 0px' } as const;

type RevealProps = {
  className?: string;
  groupClassName?: string;
  children: React.ReactNode;
};

export function Reveal({ className, groupClassName, children }: RevealProps) {
  const ref = useRef<HTMLDivElement>(null);
  const isInView = useInView(ref, ENTERED_ONCE);

  return (
    <div ref={ref} className={className}>
      <Settle isShown={isInView} className={groupClassName}>
        {children}
      </Settle>
    </div>
  );
}

const SECTION_HASH_PATTERN = /^#.+/;

export function sectionHashOf(href: string | null) {
  if (href === null) {
    return null;
  }
  const isSectionHash = SECTION_HASH_PATTERN.test(href);
  if (!isSectionHash) {
    return null;
  }
  return href;
}

export function scrollToSection(hash: string) {
  const id = hash.slice(1);
  const target = document.getElementById(id);
  target?.scrollIntoView();
}

