import { SESSION, tickPressKeyOf, type SprintState } from './sprint-session';

function titleOfId(id: string | null) {
  const task = SPRINT_TASKS.find((candidate) => candidate.id === id);
  if (!task) {
    return null;
  }
  return task.title;
}

function statusOf(state: SprintState) {
  const working = titleOfId(state.workingId);
  if (working !== null) {
    return `Working on: ${working}`;
  }
  if (state.doneIds.length === SPRINT_TASKS.length) {
    return 'Sprint done';
  }
  return 'Ready for the next task';
}

function rowToneOf(isWorking: boolean) {
  if (isWorking) {
    return 'bg-primary/[0.06]';
  }
  return 'bg-transparent';
}

function titleToneOf(isDone: boolean) {
  if (isDone) {
    return 'text-muted-foreground line-through';
  }
  return 'text-foreground';
}

type TaskRowProps = {
  task: SprintTask;
  isDone: boolean;
  isWorking: boolean;
  isTickPressed: boolean;
  onToggle: (id: string) => void;
};

function TaskRow({
  task,
  isDone,
  isWorking,
  isTickPressed,
  onToggle,
}: TaskRowProps) {
  function toggle() {
    onToggle(task.id);
  }

  return (
    <li
      className={cn(
        'flex items-center gap-3 rounded-xl p-3 transition-colors duration-300',
        rowToneOf(isWorking)
      )}
    >
      <Checkbox
        checked={isDone}
        onCheckedChange={toggle}
        aria-label={task.title}
        className={cn('size-5', pressedQuietOf(isTickPressed))}
      />
      <p
        className={cn(
          'min-w-0 flex-1 text-[13px] transition-colors duration-300',
          titleToneOf(isDone)
        )}
      >
        {task.title}
      </p>
      {isWorking && (
        <LoaderCircleIcon className='text-muted-foreground size-4 shrink-0 animate-spin' />
      )}
    </li>
  );
}

export function Sprint() {
  const { ref, isAutoplaying, state, act, pressed } = useSession(SESSION);
  const doneCount = state.doneIds.length;
  const total = SPRINT_TASKS.length;
  const status = statusOf(state);
  const message = spokenUnless(isAutoplaying, status);
  useKeptHeight(ref);

  function toggle(id: string) {
    act({ type: 'toggled', id });
  }

  return (
    <section
      id={SPRINT_ANCHOR}
      className='px-4 py-16 @sm:px-6 @sm:py-20 @5xl:px-8'
    >
      <Reveal
        className='mx-auto max-w-6xl'
        groupClassName='grid items-center gap-8 @4xl:grid-cols-[minmax(0,2fr)_minmax(0,3fr)] @4xl:gap-16'
      >
        <SettleItem className='flex max-w-xl flex-col gap-3'>
          <h2 className='text-2xl font-semibold text-balance @2xl:text-3xl'>
            {SPRINT_SECTION.title}
          </h2>
          <p className='text-muted-foreground text-base text-pretty'>
            {SPRINT_SECTION.description}
          </p>
        </SettleItem>
        <SettleItem>
          <div
            ref={ref}
            className='bg-foreground/[0.03] min-h-[27rem] rounded-2xl p-2 @3xl:p-3'
          >
            <div className='bg-card hairline-ring ring-border dark:bg-foreground/[0.04] flex flex-col gap-4 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
              <div className='flex items-center gap-3'>
                <MeshTile
                  seed={SPRINT_SECTION.agent}
                  color={seriesColorOf(3)}
                  size='lg'
                />
                <div className='flex min-w-0 flex-col gap-0.5'>
                  <p className='text-sm font-medium'>{SPRINT_SECTION.agent}</p>
                  <p className='text-muted-foreground truncate text-xs'>
                    <Swap swapKey={status}>{status}</Swap>
                  </p>
                </div>
                <p className='text-muted-foreground ms-auto shrink-0 text-xs tabular-nums'>
                  {SPRINT_SECTION.sprint}
                </p>
              </div>
              <Progress
                value={(doneCount / total) * 100}
                aria-label='Sprint progress'
                className='gap-0'
              />
              <p className='text-muted-foreground text-xs tabular-nums'>
                <MotionNumber value={doneCount} /> of {total} done
              </p>
              <ul className='flex flex-col'>
                {SPRINT_TASKS.map((task) => (
                  <TaskRow
                    key={task.id}
                    task={task}
                    isDone={state.doneIds.includes(task.id)}
                    isWorking={state.workingId === task.id}
                    isTickPressed={pressed === tickPressKeyOf(task.id)}
                    onToggle={toggle}
                  />
                ))}
              </ul>
            </div>
            <LiveRegion message={message} />
          </div>
        </SettleItem>
      </Reveal>
    </section>
  );
}

'use client';

import { useState } from 'react';

import { useAutoplay } from '@/registry/ndeko/hooks/use-autoplay';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Fold } from '@/registry/ndeko/ui/chat-motion';
import { DrawnCheck } from '@/registry/ndeko/ui/drawn-check';

import { TASK_CAPTURE } from './data';

type CaptureStage = 0 | 1 | 2 | 3;

const STEP_MS = 1200;

function stageOf(stage: CaptureStage, shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return 3;
  }
  return stage;
}

function phraseToneOf(isMarked: boolean) {
  if (isMarked) {
    return 'bg-primary/15 text-foreground';
  }
  return 'bg-transparent';
}

export function TaskCapture() {
  const [rawStage, setRawStage] = useState<CaptureStage>(0);
  const shouldReduceMotion = usePrefersReducedMotion();
  const stage = stageOf(rawStage, shouldReduceMotion);
  const steps = [
    { after: 1400, run: () => setRawStage(1) },
    { after: STEP_MS, run: () => setRawStage(2) },
    { after: STEP_MS, run: () => setRawStage(3) },
  ];
  const { ref } = useAutoplay(steps, {
    loopAfter: 2200,
    onReset: () => setRawStage(0),
  });
  const isMarked = stage >= 1;
  const isTaskShown = stage >= 2;
  const isDone = stage >= 3;

  return (
    <div ref={ref} className='flex flex-col gap-3'>
      <p className='bg-card hairline-ring ring-border rounded-xl px-3 py-2.5 text-[13px]'>
        {TASK_CAPTURE.noteLead}{' '}
        <span
          className={cn(
            'rounded-sm px-0.5 transition-colors duration-300',
            phraseToneOf(isMarked)
          )}
        >
          {TASK_CAPTURE.notePhrase}
        </span>
      </p>
      <Fold open={isTaskShown}>
        <div className='bg-card hairline-ring ring-border flex items-center gap-3 rounded-xl px-3 py-2.5'>
          <span className='flex size-[18px] shrink-0 items-center justify-center'>
            {isDone && <DrawnCheck tone='success' label='Done' />}
            {!isDone && (
              <span className='border-foreground/25 size-4 rounded-full border' />
            )}
          </span>
          <p className='min-w-0 flex-1 truncate text-[13px] font-medium'>
            {TASK_CAPTURE.task}
          </p>
          <Badge variant='secondary'>{TASK_CAPTURE.due}</Badge>
        </div>
      </Fold>
    </div>
  );
}

